package io.github.jesterportfolio.hearth.auraprobe;

import java.util.*;import java.util.concurrent.*;import java.nio.file.*;
import org.bukkit.*;import org.bukkit.event.*;import org.bukkit.inventory.ItemStack;import org.bukkit.enchantments.Enchantment;
import com.google.gson.*;
import dev.aurelium.auraskills.api.*;import dev.aurelium.auraskills.api.registry.*;import dev.aurelium.auraskills.api.skill.*;import dev.aurelium.auraskills.api.stat.*;import dev.aurelium.auraskills.api.trait.*;import dev.aurelium.auraskills.api.ability.*;import dev.aurelium.auraskills.api.mana.*;import dev.aurelium.auraskills.api.item.*;import dev.aurelium.auraskills.api.util.AuraSkillsModifier.Operation;
import dev.aurelium.auraskills.api.event.skill.SkillsLoadEvent;
import dev.aurelium.auraskills.bukkit.AuraSkills;import dev.aurelium.auraskills.common.user.User;
import com.sk89q.worldguard.WorldGuard;import com.sk89q.worldguard.protection.regions.*;import com.sk89q.worldguard.protection.flags.*;import com.sk89q.worldguard.domains.*;import com.sk89q.worldedit.bukkit.BukkitAdapter;import com.sk89q.worldedit.math.BlockVector3;

/** API/오프라인 데이터 계약만 검증합니다. Player 인스턴스나 실제 행동을 만들지 않습니다. */
public final class AuraChecks implements Listener {
 private final AuraProbePlugin p;private final AuraSkills aura;private final AuraSkillsApi api;private boolean ready;private final CustomSkill skill;private final CustomStat stat;private final CustomAbility passive;private final CustomManaAbility active;
 private static final UUID USER=new UUID(0x41555241,1);
 public AuraChecks(AuraProbePlugin p){this.p=p;aura=(AuraSkills)Bukkit.getPluginManager().getPlugin("AuraSkills");api=AuraSkillsApi.get();try{Files.createDirectories(p.getDataFolder().toPath());Files.writeString(p.getDataFolder().toPath().resolve("skills.yml"),"skills:\n  hearthprobe/metallurgy:\n    mana_ability: hearthprobe/measured_active\n");}catch(Exception e){throw new IllegalStateException(e);}var registry=api.useRegistry("hearthprobe",p.getDataFolder());passive=CustomAbility.builder(NamespacedId.of("hearthprobe","measured_passive")).baseValue(2).valuePerLevel(3).unlock(1).levelUp(1).maxLevel(100).displayName("Probe passive").description("Technical data contract only").build();active=CustomManaAbility.builder(NamespacedId.of("hearthprobe","measured_active")).baseValue(5).valuePerLevel(1).baseCooldown(10).baseManaCost(5).unlock(1).levelUp(1).maxLevel(100).displayName("Probe active").description("No gameplay activation").build();stat=CustomStat.builder(NamespacedId.of("hearthprobe","craft_power")).displayName("Probe stat").description("Technical stat").color("<white>").symbol("P").trait(Traits.ATTACK_DAMAGE,1).build();skill=CustomSkill.builder(NamespacedId.of("hearthprobe","metallurgy")).displayName("Probe metallurgy").description("Technical skill").ability(passive).manaAbility(active).build();registry.registerAbility(passive);registry.registerManaAbility(active);registry.registerStat(stat);registry.registerSkill(skill);Bukkit.getPluginManager().registerEvents(this,p);}
 @EventHandler public void loaded(SkillsLoadEvent e){ready=true;}
 public CompletionStage<Void> run(String phase){p.check(ready&&aura.isEnabled(),"official_AuraSkills_enabled_and_SkillsLoadEvent_observed");p.check(api.getGlobalRegistry().getSkill(skill.getId())==skill&&skill.isEnabled()&&stat.isEnabled(),"custom_skill_stat_passive_and_mana_ability_registered");p.check(passive.getValue(3)>passive.getValue(1)&&active.getManaCost(1)>=0&&active.getCooldown(1)>=0,"loaded_passive_formula_and_active_mana_cooldown_data_are_available");p.check(!api.getUser(UUID.randomUUID()).isLoaded(),"unloaded_API_user_is_not_admitted_as_level_ready");worldGuard();p.check(aura.getWorldManager().isBlockedWorld("hearth_policy_blocked")&&aura.getWorldManager().isDisabledWorld("hearth_policy_disabled"),"configured_world_XP_and_ability_disable_lists_are_loaded");
  if(phase.equals("restore"))return restore();
  User data=aura.getUserManager().createNewUser(USER,null);var user=data.toApi();user.setSkillLevel(Skills.MINING,5,false);user.setSkillLevel(skill,3,false);user.setSkillXp(skill,0);double requirement=api.getXpRequirements().getXpRequired(skill,4);user.addSkillXpRaw(skill,requirement+1);p.check(user.getSkillLevel(skill)>=4,"raw_API_xp_levels_custom_skill_without_fabricated_Player");double prior=user.getSkillXp(Skills.MINING);user.addSkillXp(Skills.MINING,100);p.check(user.getSkillXp(Skills.MINING)==prior,"normal_XP_pipeline_does_not_simulate_player_events_for_offline_data");user.setMana(50);p.check(user.consumeMana(5)&&user.getMana()==45,"mana_API_consume_contract_is_independent_of_player_activation");double before=user.getStatLevel(Stats.STRENGTH);data.addStatModifier(new StatModifier("hearthproof:equipment",Stats.STRENGTH,7),false);data.addStatModifier(new StatModifier("hearthproof:equipment",Stats.STRENGTH,7),false);p.check(user.getStatLevel(Stats.STRENGTH)==before+7,"stable_modifier_identity_prevents_duplicate_equipment_stats");data.removeStatModifier("hearthproof:equipment",false);p.check(user.getStatLevel(Stats.STRENGTH)==before,"modifier_removal_restores_previous_stat_total");data.addStatModifier(new StatModifier("hearthproof:persist",stat,11),false);
  var item=new ItemStack(Material.DIAMOND_SWORD);item.addUnsafeEnchantment(Enchantment.SHARPNESS,5);item.editMeta(meta->meta.getPersistentDataContainer().set(new NamespacedKey(p,"upgrade"),org.bukkit.persistence.PersistentDataType.INTEGER,3));var manager=AuraSkillsBukkit.get().getItemManager();var equipped=manager.addStatModifier(item,ModifierType.ITEM,Stats.STRENGTH,8,Operation.ADD,false);p.check(manager.getStatModifiers(equipped,ModifierType.ITEM).stream().anyMatch(m->m.value()==8)&&equipped.getEnchantmentLevel(Enchantment.SHARPNESS)==5&&equipped.getItemMeta().getPersistentDataContainer().get(new NamespacedKey(p,"upgrade"),org.bukkit.persistence.PersistentDataType.INTEGER)==3,"Aura_item_modifier_preserves_vanilla_enchant_and_custom_upgrade_PDC");var copy=ItemStack.deserializeBytes(equipped.serializeAsBytes());p.check(copy.isSimilar(equipped),"item_modifier_and_custom_metadata_survive_Paper_item_serialization");
  var expected=new JsonObject();expected.addProperty("level",user.getSkillLevel(skill));expected.addProperty("xp",user.getSkillXp(skill));expected.addProperty("mana",user.getMana());p.json("aura-storage-expected.json",expected);
  return CompletableFuture.runAsync(()->{try{aura.getStorageProvider().save(data);}catch(Exception e){throw new CompletionException(e);}},p.io()).thenRunAsync(()->p.check(Files.isRegularFile(aura.getDataFolder().toPath().resolve("userdata").resolve(USER+".yml")),"real_YAML_userdata_is_written_for_synthetic_offline_record"),p.owner()).thenCompose(v->ioBenchmark()).thenRunAsync(this::apiBenchmark,p.owner());
 }
 private CompletionStage<Void> restore(){return api.getUserManager().loadUser(USER).thenAcceptAsync(user->{try{var expected=JsonParser.parseString(Files.readString(p.root.resolve("aura-storage-expected.json"))).getAsJsonObject();p.check(user.isLoaded()&&user.getSkillLevel(skill)==expected.get("level").getAsInt()&&Math.abs(user.getSkillXp(skill)-expected.get("xp").getAsDouble())<1e-9&&user.getMana()==expected.get("mana").getAsDouble(),"second_JVM_restores_custom_skill_level_XP_and_mana_from_YAML");p.check(user.getStatModifiers().containsKey("hearthproof:persist"),"second_JVM_restores_named_custom_stat_modifier");var hud=Bukkit.getPluginManager().getPlugin("BetterHud");p.check(hud!=null&&hud.isEnabled(),"fixed_BetterHud_and_AuraSkills_and_Hearth_coexist_at_boot");}catch(Exception e){throw new CompletionException(e);}},p.owner());}
 private CompletionStage<Void> ioBenchmark(){var users=new ArrayList<User>();for(int i=0;i<100;i++){var u=aura.getUserManager().createNewUser(new UUID(0x41555242,i),null);u.setSkillLevel(Skills.MINING,5);u.setSkillXp(skill,10);users.add(u);}return CompletableFuture.runAsync(()->{long start=System.nanoTime();try{for(var u:users)aura.getStorageProvider().save(u);long saved=System.nanoTime();for(var u:users)aura.getStorageProvider().loadState(u.getUuid());long read=System.nanoTime();var metrics=new JsonObject();metrics.addProperty("offline_records",users.size());metrics.addProperty("write_ms",(saved-start)/1e6);metrics.addProperty("read_ms",(read-saved)/1e6);metrics.addProperty("simultaneous_players",0);p.json("aura-yaml-io.json",metrics);}catch(Exception e){throw new CompletionException(e);}},p.io()).thenRunAsync(()->p.check(true,"bounded_100_record_YAML_write_read_benchmark_completed_off_main_thread"),p.owner());}
 private void apiBenchmark(){var u=aura.getUserManager().createNewUser(new UUID(0x41555243,1),null).toApi();u.setSkillLevel(Skills.MINING,5,false);long start=System.nanoTime();long sum=0;for(int i=0;i<100000;i++)sum+=u.getSkillLevel(Skills.MINING);var metrics=new JsonObject();metrics.addProperty("reads",100000);metrics.addProperty("milliseconds",(System.nanoTime()-start)/1e6);metrics.addProperty("checksum",sum);p.json("aura-api-cache-bench.json",metrics);p.check(sum>0,"bounded_cached_level_read_benchmark_completed_without_database_calls");}
 private void worldGuard(){var w=Bukkit.getWorlds().getFirst();var m=WorldGuard.getInstance().getPlatform().getRegionContainer().get(BukkitAdapter.adapt(w));p.check(m!=null&&WorldGuard.getInstance().getFlagRegistry().get("auraskills-xp-gain")!=null,"official_WorldGuard_hook_registers_AuraSkills_region_flags");var r=new ProtectedCuboidRegion("hearth_aura_probe",BlockVector3.at(128,w.getMinHeight(),128),BlockVector3.at(143,w.getMaxHeight()-1,143));r.setPriority(5000);r.getOwners().addPlayer(USER);UUID friend=new UUID(0x41555241,2);r.getMembers().addPlayer(friend);r.setFlag(Flags.BLOCK_BREAK,StateFlag.State.DENY);r.setFlag(Flags.BLOCK_BREAK.getRegionGroupFlag(),RegionGroup.NON_OWNERS);r.setFlag(Flags.CHEST_ACCESS,StateFlag.State.ALLOW);r.setFlag(Flags.CHEST_ACCESS.getRegionGroupFlag(),RegionGroup.MEMBERS);r.setFlag(Flags.PVP,StateFlag.State.DENY);m.addRegion(r);var set=m.getApplicableRegions(BlockVector3.at(130,70,130));p.check(set.testState(regions->Association.MEMBER,Flags.CHEST_ACCESS)&&!set.testState(regions->Association.MEMBER,Flags.BLOCK_BREAK)&&!set.testState(regions->Association.NON_MEMBER,Flags.CHEST_ACCESS),"WG_queries_separate_named_member_chest_access_from_building");r.setFlag(Flags.CHEST_ACCESS,StateFlag.State.ALLOW);r.setFlag(Flags.CHEST_ACCESS.getRegionGroupFlag(),RegionGroup.ALL);p.check(set.testState(regions->Association.NON_MEMBER,Flags.CHEST_ACCESS)&&!set.testState(regions->Association.NON_MEMBER,Flags.BLOCK_BREAK)&&!set.testState(regions->Association.OWNER,Flags.PVP),"WG_public_container_access_and_PvP_denial_do_not_require_public_building");r.setFlag(Flags.PVP,StateFlag.State.ALLOW);p.check(set.testState(regions->Association.OWNER,Flags.PVP),"WG_region_PvP_flag_can_be_changed_for_private_owner_policy");}
}
